 if(this.mode==='siege'||this.mode==='imperial'){this.players[0].era=this.mode==='imperial'?3:2;this.players[0].stock={food:1000,wood:1200,gold:900,stone:1100};this.add('building','siege',0,-24,-13);this.add('building','keep',1,20,18);for(let i=0;i<7;i++)this.add('building',i===3?'gate':'wall',1,12+i*2.5,7);for(const [i,id]of ['ram','ram','swordsman','swordsman','archer','archer'].entries())this.add('unit',id,0,-13+i*2,-5);}
 for(const [cx,cz] of [[-48,15],[-46,-48],[0,-46],[48,-12],[47,47],[-14,45]]){for(let i=0;i<24;i++){const angle=this.random()*Math.PI*2,r=Math.sqrt(this.random())*7;this.node('wood',cx+Math.cos(angle)*r,cz+Math.sin(angle)*r,160+Math.floor(this.random()*80));}}
