 for(const [x,z] of [[-86,65],[-5,-83],[45,84],[-102,-55],[53,-60],[-26,91]]){for(let k=0;k<3;k++)this.node(k===0?'stone':'gold',x+k*2.5,z,1600);this.node('food',x-6,z+6,700);}
