 canTrain(e:Entity,d:UnitDef){return e.type==='building'&&e.progress>=1&&(d.building===e.def||(e.def==='town'&&['worker','explorer','scout'].includes(d.id))||(e.def==='keep'&&d.factions?.includes(this.players[e.owner].faction)))&&this.available(d,e.owner);}
 train(building:Entity,id:string){const d=UNITS[id];if(!d||!this.canTrain(building,d))return false;if(building.queue.length>=12||!this.pay(building.owner,d.cost))return false;building.queue.push({unit:id,progress:0,reserved:false});return true;}
